def paint(n: int, ops: list[list[int]]) -> list[list[int]]:
    pts = {1, n + 1}
    for op in ops:
        pts.add(op[1])
        pts.add(op[2] + 1)
    xs = sorted(pts)
    pos = {x: i for i, x in enumerate(xs)}
    m = len(xs) - 1

    size = 4 * m
    is_assign = [False] * size
    val = [0] * size

    def push(node):
        for child in (2 * node, 2 * node + 1):
            if is_assign[node]:
                is_assign[child] = True
                val[child] = val[node]
            elif val[node] > val[child]:
                val[child] = val[node]
        is_assign[node] = False
        val[node] = 0

    def update(node, lo, hi, l, r, assign, v):
        if r < lo or hi < l:
            return
        if l <= lo and hi <= r:
            if assign:
                is_assign[node] = True
                val[node] = v
            elif v > val[node]:
                val[node] = v
            return
        push(node)
        mid = (lo + hi) // 2
        update(2 * node, lo, mid, l, r, assign, v)
        update(2 * node + 1, mid + 1, hi, l, r, assign, v)

    def collect(node, lo, hi, res):
        if lo == hi:
            res[lo] = val[node]
            return
        push(node)
        mid = (lo + hi) // 2
        collect(2 * node, lo, mid, res)
        collect(2 * node + 1, mid + 1, hi, res)

    for op in ops:
        a = pos[op[1]]
        b = pos[op[2] + 1] - 1
        if op[0] == 1:
            update(1, 0, m - 1, a, b, False, op[3])
        else:
            update(1, 0, m - 1, a, b, True, 0)

    res = [0] * m
    collect(1, 0, m - 1, res)

    counts = {}
    for i, c in enumerate(res):
        if c:
            counts[c] = counts.get(c, 0) + xs[i + 1] - xs[i]

    return [[c, counts[c]] for c in sorted(counts)]
